import org.jetbrains.kotlin.gradle.ExperimentalWasmDsl
import org.jetbrains.kotlin.gradle.dsl.JvmTarget

// Tests only, never published. It is what shows the Metro bindings generated by eventus-ksp working: the
// processor's own tests compile the generated code, and only Metro's compiler plugin can build a graph from it.
plugins {
    alias(libs.plugins.kotlin.multiplatform)
    alias(libs.plugins.metro)
    alias(libs.plugins.ksp)
}

kotlin {
    jvm {
        compilerOptions { jvmTarget.set(JvmTarget.JVM_11) }
    }

    iosSimulatorArm64()

    @OptIn(ExperimentalWasmDsl::class)
    wasmJs { nodejs() }

    js { nodejs() }

    sourceSets {
        commonMain.dependencies {
            implementation(projects.eventus)
            implementation(projects.eventusMetro)
        }

        commonTest.dependencies {
            implementation(libs.kotlin.test)
            implementation(libs.kotlinx.coroutines.test)
        }
    }
}

// The Eventus processor, once per target: it writes the Metro bindings of each screen into that target.
dependencies {
    add("kspJvm", projects.eventusKsp)
    add("kspIosSimulatorArm64", projects.eventusKsp)
    add("kspWasmJs", projects.eventusKsp)
    add("kspJs", projects.eventusKsp)
}
